// Bundles the skill scripts (unmodified) into browser globals:
//   js/engine.js  -> window.P        (physics-2d)
//   js/atelier.js -> window.Shading, window.Easing, window.Noise
const fs = require('fs');
const path = require('path');
const root = path.join(__dirname, '..');

function bundleCommonJS(dir, files, globalName, entry) {
  let out = `// AUTO-GENERATED by tools/bundle.js from .claude/skills — do not edit.\n(function(){\n`;
  out += `const __defs={},__mods={};function define(n,f){__defs[n]=f;}\n`;
  out += `function __require(n){n=n.replace('./','');if(__mods[n])return __mods[n].exports;const module={exports:{}};__mods[n]=module;__defs[n](module,module.exports,__require);return module.exports;}\n`;
  for (const f of files) {
    const src = fs.readFileSync(path.join(dir, f), 'utf8');
    out += `define(${JSON.stringify(f)}, function(module, exports, require){\n${src}\n});\n`;
  }
  out += `window.${globalName}=__require(${JSON.stringify(entry)});\n})();\n`;
  return out;
}

const phys = path.join(root, '.claude/skills/physics-2d/scripts');
fs.writeFileSync(path.join(root, 'js/engine.js'), bundleCommonJS(phys,
  ['vec2.js','shapes.js','body.js','broadphase.js','collision.js','solver.js','constraints.js','raycast.js','world.js','index.js'],
  'P', 'index.js'));

const at = path.join(root, '.claude/skills/canvas-atelier/scripts');
let a = `// AUTO-GENERATED by tools/bundle.js from .claude/skills — do not edit.\n`;
for (const f of ['shading.js','easing.js','noise.js']) {
  a += `\n// ---- ${f} ----\n` + fs.readFileSync(path.join(at, f), 'utf8').replace(/if \(typeof module[^\n]*\n?/g, '');
}
fs.writeFileSync(path.join(root, 'js/atelier.js'), a);
console.log('bundled');
